SELECT MARKET, SUM(IFF(FISCAL_YEAR = 2025, GROSS_PROFIT, 0)) AS GP_FY25, SUM(IFF(FISCAL_YEAR = 2026, GROSS_PROFIT, 0)) AS GP_FY26
FROM SDP_LINK.PUBLIC.LINK_GP_MONTHLY
GROUP BY 1 ORDER BY GP_FY26 DESC;

SELECT PRODUCT_FAMILY, SUM(GROSS_PROFIT) AS GP_FY26
FROM SDP_LINK.PUBLIC.LINK_GP_MONTHLY WHERE FISCAL_YEAR = 2026
GROUP BY 1 ORDER BY 2 DESC;

SELECT PRODUCT_FAMILY, SUM(GROSS_PROFIT) / NULLIF(SUM(MESSAGES), 0) * 100 AS GP_ORE_PER_MSG
FROM SDP_LINK.PUBLIC.LINK_GP_MONTHLY WHERE FISCAL_YEAR = 2026
GROUP BY 1 ORDER BY 2 DESC;

SELECT ROUTE_TYPE, SUM(TERMINATION_COST) AS TERMINATION_FY26
FROM SDP_LINK.PUBLIC.LINK_ROUTE_COST WHERE FISCAL_YEAR = 2026
GROUP BY 1 ORDER BY 2 DESC;

SELECT VERSION_NAME, SUM(IFF(ACCOUNT_ID = 'gp', AMOUNT, 0)) AS GP, SUM(IFF(ACCOUNT_ID = 'ebitda', AMOUNT, 0)) AS ADJ_EBITDA
FROM SDP_LINK.PUBLIC.V_CALCULATED_STATEMENT WHERE FISCAL_YEAR = 2026
GROUP BY 1;
